 if action=="selftest":
  cases=[("run","anqr","typecheck","develop","x",False),("run","anqr","deploy","a"*40,"x",False),("run","cix","test","a"*40,"../x",False),("run","unknown","test","a"*40,"x",False),("status","cix","","","x",True)]
