 args={"action":"status" if action=="status" else "run","job_id":"pc1-"+project+"-"+operation_id}
 if action!="status":
  request={"action":action,"project":project,"target":target,"expected_commit":expected_commit,"operation_id":operation_id,"install_locked":install_locked,"source_branch":source_branch}
